function sparseDot(a: number[], b: number[]): number {
  const compact = (v: number[]) => {
    const out: [number, number][] = [];
    v.forEach((x, i) => { if (x !== 0) out.push([i, x]); });
    return out;
  };
  const pa = compact(a), pb = compact(b);
  let i = 0, j = 0, total = 0;
  while (i < pa.length && j < pb.length) {
    if (pa[i][0] === pb[j][0]) total += pa[i++][1] * pb[j++][1];
    else if (pa[i][0] < pb[j][0]) i++;
    else j++;
  }
  return total;
}

